const nonproportionalTable=family('fixed-fee-table','detect a nonzero intercept from a table',c=>{const rate=c.n(2,17),fee=c.n(3,29);return choose('The table lists rental cost C for hours h. Which statement explains why C is not proportional to h?', ['At h=0, C is '+fee+', rather than 0.','The hourly change in cost is constant.','Cost increases with hours.','The table includes numerical values.'],0,['A nonzero zero-input output prevents a model C=kh.','A constant rate of change can occur even with a fixed fee.','Increasing relationships can be proportional or nonproportional.','Numerical data alone does not establish proportionality.'],[`The table's zero-hour cost is ${fee}.`,`A proportional relationship must pass through (0,0), so this fixed cost prevents proportionality.`],'Check the zero-input row and whether output/input is a fixed quotient.','A constant difference between rows is not enough for direct proportionality.',{table:{headers:['Hours h','Cost C'],rows:[[0,fee],[1,fee+rate],[2,fee+2*rate],[3,fee+3*rate]]},scenario:'fixed-fee rental table'})});
const nonproportionalChoice=family('choose-nonproportional-model','distinguish a fixed addition from pure scaling',c=>{const a=c.n(2,17),b=c.n(3,19);return choose('Which relationship is NOT proportional?', [`y=${a}x+${b}`,`y=${a}x`,`y=${b}x`,`y=x/${a}`],0,['The nonzero added constant means y is not zero when x=0.','This is the proportional form y=kx.','This is another constant-multiplier relationship.','This is y=(1/'+a+')x, with a fixed proportional multiplier.'],[`For y=${a}x+${b}, setting x=0 gives y=${b}.`,`The other models all have the form y=kx and pass through the origin.`],'Look for a nonzero fixed addition when distinguishing proportional and nonproportional models.','Dividing x by a fixed nonzero number is still multiplication by a constant reciprocal.',{scenario:'relationship classification'})});
supplement('Identifying non-proportional relationships',[nonproportional,nonproportionalTable,nonproportionalChoice],true);
const ratioFraction=family('ratio-part-as-fraction','convert a part-to-part ratio into a part of the whole',c=>{const{a,b}=quantities(c);return number(`The ratio of red to blue beads is ${a}:${b}. What fraction of all beads is red?`,a/(a+b),[wrong(a/b,'This compares red to blue rather than red to all beads.'),wrong(b/(a+b),'This is the blue share.'),wrong((a+b)/a,'This reverses part and whole.')],[`One complete group contains ${a}+${b}=${a+b} beads.`,`The red share is ${a}/${a+b}=${frac(a,a+b)} of the whole.`],'Add all ratio parts to form the whole before writing a part-to-whole fraction.','The second part alone is not the whole denominator.',{scenario:'red bead share'})});
