const ratioPercentPart=family('ratio-then-percent-of-part','apply a percent to a part recovered by a ratio',c=>{const{a,b,k}=quantities(c),factor=4*k,p=c.pick([25,50,75]),total=(a+b)*factor,red=a*factor;return number(`Red and blue badges have ratio ${a}:${b}, with ${total} badges altogether. ${p}% of the red badges are distributed. How many red badges are distributed?`,red*p/100,[wrong(total*p/100,'The stated percent applies only to the red part, not to all badges.'),wrong(red,'This is the whole red part before taking the distributed percent.'),wrong(red*(100-p)/100,'This counts the red badges left rather than distributed.')],[`There are ${a+b} ratio parts, each containing ${total}/${a+b}=${factor} badges.`,`Red count = ${a} × ${factor}=${red}.`,`Distributed red count = ${red} × ${p}/100=${red*p/100}.`],'Recover the named ratio part before applying a percentage whose base is that part.','The word following “percent of” identifies the correct base.',{scenario:'distributed red badges'})});
const ratioPercentChange=family('ratio-after-percent-removal','update composition before finding a percent share',c=>{const{a,b,k}=quantities(c),factor=4*k,p=c.pick([25,50,75]),red=a*factor,blue=b*factor,remainingBlue=blue*(100-p)/100,whole=red+remainingBlue;return number(`Red and blue counters have ratio ${a}:${b}, with ${red} red counters. ${p}% of the blue counters are removed. What percent of the remaining counters is red?`,100*red/whole,[wrong(100*a/(a+b),'This is the original red share before the blue removal.'),wrong(100*red/remainingBlue,'This compares red to blue rather than red to the new whole.'),wrong(100*remainingBlue/whole,'This is the remaining blue share instead of the red share.')],[`The original blue count is ${red}/${a} × ${b}=${blue}.`,`Remaining blue = ${blue} × ${100-p}/100=${remainingBlue}.`,`New whole = ${red}+${remainingBlue}=${whole}.`,`Red percent = ${red}/${whole} × 100=${fmt(100*red/whole)}%.`],'Apply the stated change to the correct ratio part, then rebuild the whole for the final percent comparison.','An original ratio need not remain valid after one part changes.',{scenario:'updated counter composition'})});
