function random(seed:number){let state=seed>>>0;return()=>{state=(state+0x6D2B79F5)>>>0;let x=Math.imul(state^(state>>>15),1|state);x^=x+Math.imul(x^(x>>>7),61|x);return((x^(x>>>14))>>>0)/4294967296}}
function hash(source:string){let value=2166136261;for(const char of source)value=Math.imul(value^char.charCodeAt(0),16777619);return(value>>>0).toString(36)}
function resolve(subtopicId:string){const topic=SUBTOPICS.find(s=>s.id===subtopicId&&s.kind==='math'),families=registry.get(subtopicId);if(!topic||!families?.length)throw new Error(`Unsupported Math subtopic: ${subtopicId}`);return{topic,families}}
export function mathFamilies(subtopicId:string):string[]{const{families}=resolve(subtopicId);return families.map(f=>`${subtopicId}:${f.name}`)}
/** Fresh content is separate from math.ts so saved v1/v2 answer indices remain immutable. */
export function generateMathV3(subtopicId:string,difficulty:number,seed:number,preferredFamily?:string):Question{
  if(!Number.isInteger(difficulty)||difficulty<1||difficulty>5)throw new Error('Math difficulty must be an integer from 1 to 5.');
  if(!Number.isSafeInteger(seed))throw new Error('Math seed must be a safe integer.');
  const{topic,families}=resolve(subtopicId),r=random(seed),n=(a:number,b:number)=>a+Math.floor(r()*(b-a+1)),pick=<T>(values:T[])=>values[n(0,values.length-1)];
  const selected=preferredFamily?families.find(f=>f.name===preferredFamily||`${subtopicId}:${f.name}`===preferredFamily):pick(families);
  if(!selected)throw new Error(`Unsupported family for ${subtopicId}: ${preferredFamily}`);
  let draft:Draft|undefined;
  // A parameter draw occasionally makes two authored error answers coincide.
  // Regenerate parameters instead of inserting meaningless nearby numbers.
  for(let attempt=0;attempt<32;attempt++){
    const candidate=selected.build({d:difficulty,n,pick,topic});
    if(candidate.options){if(candidate.options.length===4&&new Set(candidate.options).size===4){draft=candidate;break}}
    else if(Number.isFinite(candidate.answer)&&candidate.errors?.some(e=>Number.isFinite(e.value)&&fmt(e.value)!==fmt(candidate.answer!))){draft=candidate;break}
  }
  if(!draft)throw new Error(`Unable to generate a valid ${subtopicId} ${selected.name} item.`);
  const options:{text:string;reason:string;correct:boolean}[]=[];
  if(draft.options)draft.options.forEach((text,index)=>options.push({text,correct:index===draft.correct,reason:draft.reasons?.[index]||''}));
  else{
    const answer=fmt(draft.answer!),errors=[...new Map((draft.errors||[]).filter(e=>Number.isFinite(e.value)&&fmt(e.value)!==answer).map(e=>[fmt(e.value),e])).values()];
    options.push({text:answer,reason:`This satisfies the stated relationships: ${draft.steps.join(' ')}`,correct:true});
    errors.slice(0,3).forEach(e=>options.push({text:fmt(e.value),reason:e.reason,correct:false}));
  }
  const grid=!draft.options&&(options.length<4||n(0,4)===0);
  for(let i=options.length-1;i>0;i--){const j=n(0,i);[options[i],options[j]]=[options[j],options[i]]}
  const familyId=`${subtopicId}:${selected.name}`,scenarioId=slug(draft.scenario||'symbolic-mathematics'),structureId=draft.structure||selected.name;
  const text=draft.text+(grid?' Give an exact fraction or a decimal rounded to four decimal places.':'');
  const signature=hash(JSON.stringify({subtopicId,familyId,scenarioId,structureId,text,table:draft.table,diagram:draft.diagram}));
  const q:Question={id:`math-v3-${slug(topic.label)}-${slug(selected.name)}-${difficulty}-${seed}-${signature}`,subject:'Math',skill:topic.skill,difficulty,text,
    type:grid?'grid':'mc',correct:grid?draft.answer!:options.findIndex(o=>o.correct),...(grid?{}:{choices:options.map(o=>o.text),distractorReasons:options.map(o=>o.reason)}),
    explanation:draft.think+'\n'+draft.steps.map((step,index)=>`${index+1}. ${step}`).join('\n'),breakthrough:draft.think,commonTrap:draft.trap,
    domain:topic.domain,topic:topic.skill,subtopic:topic.id,subskill:topic.label,familyId,scenarioId,structureId,reasoningType:selected.reasoning,
    reasoningSteps:draft.steps.length,misconception:draft.trap,howToThink:draft.think,solutionSteps:draft.steps,evidenceExplanation:`Check the result against the original information. ${draft.steps.at(-1)}`,
    estimatedTime:Math.min(240,35+draft.steps.length*20+(difficulty-1)*10),calibration:{basis:'Authored middle-school task structure and reasoning steps; awaiting response-based calibration.',status:'editorial',version:3},
    qualityVersion:3,contentSignature:signature,templateId:familyId,generationMethod:'procedural-v3',...(draft.table?{table:draft.table}:{}),...(draft.diagram?{diagram:draft.diagram}:{})};
  const errors=validate(q);if(errors.length)throw new Error(`${q.id}: ${errors.join(' ')}`);return q;
}
